css:
.pivot-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Fira Code', monospace;
    color: #c9d1d9;
}
.pivot-sim-header {
    border-left: 4px solid #00bfff;
    padding: 24px 28px;
    margin-bottom: 24px;
    background: rgba(0,191,255,0.04);
    position: relative;
}
.pivot-sim-header-tag {
    display: inline-block;
    background: rgba(0,191,255,0.15);
    color: #00bfff;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 3px;
    margin-bottom: 10px;
}
.pivot-sim-header h1 {
    color: #00bfff;
    font-size: 1.6rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    font-weight: 700;
}
.pivot-sim-subtitle {
    color: #8b9dc3;
    font-size: 0.82rem;
    margin: 0;
    letter-spacing: 0.04em;
}
.pivot-sim-period-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 6px;
    padding: 12px 20px;
    margin-bottom: 24px;
    font-size: 0.9rem;
    color: #8b9dc3;
}
.pivot-sim-period-bar span:nth-child(2),
.pivot-sim-period-bar span:nth-child(4) {
    color: #00bfff;
    font-weight: 700;
    font-size: 1.1rem;
}
.pivot-sim-round-tag {
    margin-left: auto;
    background: rgba(0,191,255,0.12);
    color: #00bfff;
    padding: 4px 14px;
    border-radius: 4px;
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}
.pivot-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(155px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.pivot-sim-kpi-card {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    padding: 18px 14px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease;
}
.pivot-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00bfff, #0066cc);
}
.pivot-sim-kpi-card:hover {
    border-color: #2a3f5f;
}
.pivot-sim-kpi-danger::before {
    background: linear-gradient(90deg, #ff4757, #ff6b81);
}
.pivot-sim-kpi-label {
    color: #8b9dc3;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 8px;
}
.pivot-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #e0e6f0;
}
.pivot-sim-kpi-accent {
    color: #00bfff;
}
.pivot-sim-kpi-green {
    color: #00ff88;
}
.pivot-sim-kpi-danger .pivot-sim-kpi-value {
    color: #ff4757;
}
.pivot-sim-briefing {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    margin-bottom: 24px;
    overflow: hidden;
}
.pivot-sim-briefing-bar {
    background: rgba(0,191,255,0.08);
    padding: 12px 20px;
    font-size: 0.78rem;
    color: #00bfff;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    display: flex;
    align-items: center;
    gap: 8px;
    border-bottom: 1px solid #1e2d42;
}
.pivot-sim-briefing-icon {
    font-size: 0.7rem;
}
.pivot-sim-briefing-body {
    padding: 20px;
    font-size: 0.85rem;
    line-height: 1.7;
    color: #9aa5b4;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.pivot-sim-controls {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
}
.pivot-sim-controls h3 {
    color: #00bfff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1e2d42;
}
.pivot-sim-control-group {
    margin-bottom: 20px;
}
.pivot-sim-control-group label {
    display: block;
    color: #8b9dc3;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
}
.pivot-sim-range-row {
    display: flex;
    align-items: center;
    gap: 12px;
}
.pivot-sim-range-end {
    color: #8b9dc3;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    min-width: 80px;
}
.pivot-sim-range-end:last-child {
    text-align: right;
}
.pivot-sim-range {
    flex: 1;
    -webkit-appearance: none;
    appearance: none;
    height: 6px;
    background: #1e2d42;
    border-radius: 3px;
    outline: none;
}
.pivot-sim-range::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #00bfff;
    cursor: pointer;
    box-shadow: 0 0 8px rgba(0,191,255,0.4);
    transition: box-shadow 0.2s ease;
}
.pivot-sim-range::-webkit-slider-thumb:hover {
    box-shadow: 0 0 14px rgba(0,191,255,0.7);
}
.pivot-sim-range::-moz-range-thumb {
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #00bfff;
    cursor: pointer;
    border: none;
    box-shadow: 0 0 8px rgba(0,191,255,0.4);
}
.pivot-sim-range-readout {
    text-align: center;
    color: #00bfff;
    font-size: 1.1rem;
    font-weight: 700;
    margin-top: 6px;
}
.pivot-sim-controls input[type="number"] {
    background: #0a0f1e;
    border: 1px solid #2a3f5f;
    color: #e0e6f0;
    border-radius: 5px;
    padding: 10px 14px;
    width: 100%;
    font-family: 'Courier New', monospace;
    font-size: 1rem;
    transition: border-color 0.2s ease;
}
.pivot-sim-controls input[type="number"]:focus {
    border-color: #00bfff;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0,191,255,0.15);
}
.pivot-sim-input-hint {
    display: block;
    color: #8b9dc3;
    font-size: 0.7rem;
    margin-top: 4px;
}
.pivot-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 24px;
}
.pivot-sim-submit-btn {
    background: linear-gradient(135deg, #0077cc, #00bfff);
    border: none;
    color: #fff;
    padding: 12px 32px;
    border-radius: 6px;
    font-family: 'Courier New', monospace;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    cursor: pointer;
    transition: box-shadow 0.2s ease, transform 0.1s ease;
}
.pivot-sim-submit-btn:hover {
    box-shadow: 0 0 16px rgba(0,191,255,0.4);
    transform: translateY(-1px);
}
.pivot-sim-undo-btn {
    background: transparent;
    border: 1px solid #2a3f5f;
    color: #8b9dc3;
    padding: 8px 18px;
    border-radius: 5px;
    font-family: 'Courier New', monospace;
    font-size: 0.75rem;
    cursor: pointer;
    transition: border-color 0.2s ease;
}
.pivot-sim-undo-btn:hover {
    border-color: #8b9dc3;
    color: #8b9dc3;
}
.pivot-sim-feedback {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    margin-bottom: 24px;
    overflow: hidden;
}
.pivot-sim-feedback-bar {
    background: rgba(0,255,136,0.06);
    padding: 12px 20px;
    font-size: 0.78rem;
    color: #00ff88;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #1e2d42;
}
.pivot-sim-feedback-body {
    padding: 20px;
    font-size: 0.85rem;
    line-height: 1.7;
    color: #c9d1d9;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.pivot-sim-history {
    margin-bottom: 24px;
}
.pivot-sim-container .table {
    background: #111827;
    color: #c9d1d9;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    overflow: hidden;
    font-size: 0.8rem;
}
.pivot-sim-container .table thead th {
    background: rgba(0,191,255,0.06);
    color: #00bfff;
    border-color: #1e2d42;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px 12px;
}
.pivot-sim-container .table td {
    border-color: #1e2d42;
    padding: 8px 12px;
}
.pivot-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background: rgba(255,255,255,0.02);
}
.pivot-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 24px;
}
.pivot-sim-chart-box {
    background: #111827;
    border: 1px solid #1e2d42;
    border-radius: 8px;
    padding: 16px;
    height: 260px;
}
@media (max-width: 768px) {
    .pivot-sim-container {
        padding: 16px;
    }
    .pivot-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .pivot-sim-charts {
        grid-template-columns: 1fr;
    }
    .pivot-sim-range-row {
        flex-wrap: wrap;
    }
    .pivot-sim-range-end {
        min-width: 60px;
        font-size: 0.6rem;
    }
    .pivot-sim-btn-row {
        flex-direction: column;
    }
    .pivot-sim-submit-btn {
        width: 100%;
    }
    .pivot-sim-header h1 {
        font-size: 1.2rem;
    }
    .pivot-sim-kpi-value {
        font-size: 1.3rem;
    }
}

