(function() {
    'use strict';

    // ARPU (annual revenue per SME client, $K) — from Concept 505 §7 ($12.4K/yr).
    var ARPU = 12.4;

    class PivotAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Pivote';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    nameEn: 'PMF Analysis',
                    nameEs: 'Análisis de PMF',
                    briefingEn: '<b>The Crisis:</b> LogiTrack S.A. has 23 SME clients paying ~$12.4K/year each, zero enterprise clients, and an alarming 8% monthly churn. Your lead angel investor Diego Sánchez has sent a concerned email: <em>"I see 23 SME clients and flat 3% MoM growth. This is not what you promised. If there is no clear plan for enterprise in 90 days, I will recommend the board halt additional capital."</em><br><br><b>Your Task:</b> Analyze the data objectively. Where is product-market fit — in SME (where you have 23 paying clients) or Enterprise (where you have zero)? Set your <b>SME Focus</b> slider to reflect your analysis conclusion. Allocate a <b>research budget</b> and set your <b>risk tolerance</b> for how boldly you will present your findings to the board.',
                    briefingEs: '<b>La Crisis:</b> LogiTrack S.A. tiene 23 clientes SME pagando ~$12.4K/año cada uno, cero clientes enterprise, y un alarmante churn mensual del 8%. Tu ángel inversionista principal, Diego Sánchez, envió un email preocupado: <em>"Veo 23 clientes SME y crecimiento plano del 3% MoM. Esto no es lo que prometieron. Si no hay un plan claro para enterprise en 90 días, voy a recomendar que la junta detenga capital adicional."</em><br><br><b>Tu Tarea:</b> Analiza los datos objetivamente. ¿Dónde está el product-market fit — en SME (donde tienes 23 clientes que pagan) o en Enterprise (donde tienes cero)? Configura el control de <b>Enfoque SME</b> para reflejar tu conclusión. Asigna un <b>presupuesto de investigación</b> y define tu <b>tolerancia al riesgo</b> sobre qué tan audazmente presentarás tus hallazgos a la junta.'
                },
                {
                    nameEn: 'Pivot Design',
                    nameEs: 'Diseño del Pivote',
                    briefingEn: '<b>Decision Time:</b> Based on your PMF analysis, you must now redesign LogiTrack for the chosen market. If pivoting to SME, this means: <b>Product</b> — strip enterprise modules, build a simple mobile-first GPS tracker with fuel cost alerts. <b>Pricing</b> — switch from $800–$2000/month enterprise tiers to $20–40/vehicle/month. <b>Sales</b> — replace enterprise sales reps with Google Ads targeting "transportista Honduras" and insurance company partnerships. <b>Support</b> — shift from 24/7 phone to chat/email + self-service knowledge base.<br><br><b>Your Task:</b> <b>SME Focus</b> controls how aggressively you simplify the product. <b>Budget</b> funds engineering and design work. <b>Risk Tolerance</b> determines how much enterprise code you cut — aggressive cuts are faster but risk losing features some SME clients actually use.',
                    briefingEs: '<b>Hora de Decidir:</b> Basado en tu análisis de PMF, ahora debes rediseñar LogiTrack para el mercado elegido. Si pivotas a SME, esto significa: <b>Producto</b> — eliminar módulos enterprise, construir un rastreador GPS móvil simple con alertas de costo de combustible. <b>Pricing</b> — cambiar de $800–$2000/mes enterprise a $20–40/vehículo/mes. <b>Ventas</b> — reemplazar vendedores enterprise con Google Ads dirigido a "transportista Honduras" y alianzas con aseguradoras. <b>Soporte</b> — pasar de teléfono 24/7 a chat/email + base de conocimiento self-service.<br><br><b>Tu Tarea:</b> <b>Enfoque SME</b> controla qué tan agresivamente simplificas el producto. <b>Presupuesto</b> financia trabajo de ingeniería y diseño. <b>Tolerancia al Riesgo</b> determina cuánto código enterprise recortas — cortes agresivos son más rápidos pero arriesgan perder funcionalidades que algunos clientes SME realmente usan.'
                },
                {
                    nameEn: 'Investor Negotiation',
                    nameEs: 'Negociación con Inversionistas',
                    briefingEn: '<b>The Conversation:</b> You must face Diego Sánchez, who invested $150K expecting enterprise traction. He has already told other angels he is "confused" about your direction. The other two angels ($80K and $60K each) are now asking if the company is in a leadership crisis.<br><br>You must convince Diego that the pivot is a <b>strategic decision, not a failure</b>. Key arguments: (1) 23 clients bought without cold calls — that IS evidence of PMF. (2) Enterprise competitors like Solucar already dominate — competing costs $5M+. (3) SME first does not close the enterprise door in 18 months.<br><br><b>Your Task:</b> <b>SME Focus</b> reflects how strongly you pitch the SME commitment (75–90% is the sweet spot — committed but pragmatic). <b>Budget proposal</b> shows your growth ambition (too high = scary burn, too low = no ambition). <b>Risk Tolerance</b> reflects your willingness to offer concessions like a board CFO, additional reporting, or protective options.',
                    briefingEs: '<b>La Conversación:</b> Debes enfrentar a Diego Sánchez, quien invirtió $150K esperando tracción enterprise. Ya comentó a otros ángeles que está "confundido" sobre tu dirección. Los otros dos ángeles ($80K y $60K cada uno) ahora preguntan si la empresa tiene una crisis de liderazgo.<br><br>Debes convencer a Diego de que el pivote es una <b>decisión estratégica, no un fracaso</b>. Argumentos clave: (1) 23 clientes compraron sin cold calls — eso ES evidencia de PMF. (2) Competidores enterprise como Solucar ya dominan — competir cuesta $5M+. (3) SME primero no cierra la puerta a enterprise en 18 meses.<br><br><b>Tu Tarea:</b> <b>Enfoque SME</b> refleja qué tan fuertemente presentas el compromiso con SME (75–90% es el punto ideal — comprometido pero pragmático). <b>Propuesta de presupuesto</b> muestra tu ambición de crecimiento (muy alto = quema aterradora, muy bajo = sin ambición). <b>Tolerancia al Riesgo</b> refleja tu disposición a ofrecer concesiones como un CFO en la junta, reportes adicionales u opciones protectoras.'
                },
                {
                    nameEn: '90-Day Execution',
                    nameEs: 'Ejecución 90 Días',
                    briefingEn: '<b>Go Time:</b> The pivot is approved. You have 90 days and ~$15K additional budget. The plan: <b>Days 1–7</b> — internal all-hands meeting, reassign team. <b>Days 8–20</b> — ship simplified SME product. <b>Days 21–35</b> — launch Google Ads, contact 20 local transportistas, sign insurance partnership. <b>Days 36–60</b> — report to Diego: new clients, reduced churn, improved NRR. <b>Days 61–90</b> — build momentum toward $400K ARR for Series A pitch.<br><br><b>Your Task:</b> <b>SME Focus</b> allocates resources between SME growth and maintaining existing systems. <b>Budget</b> covers Google Ads ($3K/mo), contractor support ($2K/mo), and operations. <b>Risk Tolerance</b> sets rollout speed vs. thoroughness. Target: $400K+ ARR and churn below 6%.',
                    briefingEs: '<b>Es Hora:</b> El pivote está aprobado. Tienes 90 días y ~$15K de presupuesto adicional. El plan: <b>Días 1–7</b> — reunión general interna, reasignar equipo. <b>Días 8–20</b> — lanzar producto SME simplificado. <b>Días 21–35</b> — lanzar Google Ads, contactar 20 transportistas locales, firmar alianza con aseguradora. <b>Días 36–60</b> — reportar a Diego: nuevos clientes, churn reducido, NRR mejorado. <b>Días 61–90</b> — construir momentum hacia $400K ARR para pitch de Series A.<br><br><b>Tu Tarea:</b> <b>Enfoque SME</b> asigna recursos entre crecimiento SME y mantener sistemas existentes. <b>Presupuesto</b> cubre Google Ads ($3K/mes), soporte contratista ($2K/mes) y operaciones. <b>Tolerancia al Riesgo</b> define velocidad vs. rigurosidad del lanzamiento. Objetivo: $400K+ ARR y churn por debajo del 6%.'
                }
            ];
            // Completion briefing (shown after the final round instead of re-rendering Round 4).
            this.DONE_BRIEF = {
                en: '<b>Simulation complete.</b> All four rounds are done. Review your final KPIs and the performance summary below — use <b>Undo Last Round</b> if you want to replay the last decision.',
                es: '<b>Simulación completa.</b> Las cuatro rondas terminaron. Revisa tus KPIs finales y el resumen de desempeño abajo — usa <b>Deshacer Última Ronda</b> si quieres repetir la última decisión.'
            };
        }

        // Robust language read: canonical `.language` first, then `.currentLanguage`,
        // then <html lang>, then 'en'. (USF guide §9 / Lessons_Learned_USF_i18n_and_Modals.)
        _lang() {
            try {
                var s = window.mySimulation;
                var l = (s && (s.language || s.currentLanguage));
                if (!l && document.documentElement) l = document.documentElement.lang;
                return (l === 'es') ? 'es' : 'en';
            } catch (e) { return 'en'; }
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    arr: 285,
                    cashOnHand: 335,
                    clientsSme: 23,
                    clientsEnterprise: 0,
                    churnMonthly: 8,
                    nrr: 95,
                    investorConfidence: 50,
                    runwayMonths: 14,
                    momGrowth: 3,
                    baseOpex: 33,          // fixed monthly operating cost ($K): 12-person team + infra.
                                           // Calibrated so start runway = 335 / (33 + 15 - 285/12) = 14 mo (Concept §2).
                    arrHistory: [],
                    confidenceHistory: [],
                    churnHistory: [],
                    runwayHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    smeFocus: 75,          // default sits inside the concept's 75-90% "sweet spot" (§ R3).
                    monthlySpend: 15,
                    riskTolerance: 5
                };
            }
            this._syncInputsFromState(state);   // restore slider positions on resume/autosave-restore
            this._setupInputListeners();
            this._updateBriefing(state);
        }

        _syncInputsFromState(state) {
            var d = state.decisions || {};
            var sme = document.getElementById('smeFocusInput');
            var smeVal = document.getElementById('smeFocusValue');
            if (sme && d.smeFocus != null) { sme.value = d.smeFocus; if (smeVal) smeVal.textContent = d.smeFocus + '%'; }
            var spend = document.getElementById('monthlySpendInput');
            if (spend && d.monthlySpend != null) spend.value = d.monthlySpend;
            var risk = document.getElementById('riskToleranceInput');
            var riskVal = document.getElementById('riskToleranceValue');
            if (risk && d.riskTolerance != null) { risk.value = d.riskTolerance; if (riskVal) riskVal.textContent = d.riskTolerance; }
        }

        _setupInputListeners() {
            var smeInput = document.getElementById('smeFocusInput');
            var smeVal = document.getElementById('smeFocusValue');
            if (smeInput && smeVal) {
                smeInput.addEventListener('input', function() {
                    smeVal.textContent = smeInput.value + '%';
                });
            }
            var riskInput = document.getElementById('riskToleranceInput');
            var riskVal = document.getElementById('riskToleranceValue');
            if (riskInput && riskVal) {
                riskInput.addEventListener('input', function() {
                    riskVal.textContent = riskInput.value;
                });
            }
        }

        _updateBriefing(state) {
            var isEs = (this._lang() === 'es');
            var period = state.currentPeriod || 1;
            var briefEl = document.getElementById('briefingText');
            var roundNameEl = document.getElementById('roundNameDisplay');

            // After the final round, show a completion message rather than clamping back to Round 4.
            if (period > this.ROUNDS.length) {
                if (briefEl) briefEl.innerHTML = isEs ? this.DONE_BRIEF.es : this.DONE_BRIEF.en;
                if (roundNameEl) roundNameEl.textContent = isEs ? 'Completado' : 'Complete';
                return;
            }
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            if (briefEl) briefEl.innerHTML = isEs ? round.briefingEs : round.briefingEn;
            if (roundNameEl) roundNameEl.textContent = isEs ? round.nameEs : round.nameEn;
        }

        validateDecisions(decisions) {
            var smeInput = document.getElementById('smeFocusInput');
            if (smeInput) decisions.smeFocus = parseInt(smeInput.value);

            var spendInput = document.getElementById('monthlySpendInput');
            if (spendInput) decisions.monthlySpend = parseFloat(spendInput.value);

            var riskInput = document.getElementById('riskToleranceInput');
            if (riskInput) decisions.riskTolerance = parseInt(riskInput.value);

            if (!decisions.monthlySpend || decisions.monthlySpend < 5 || decisions.monthlySpend > 50) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('spend_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var arrChangeRaw = 0;      // gross ARR added by the round's decisions (before churn) — kept for feedback
            var churnChange = 0;
            var confidenceChange = 0;
            var newClients = 0;

            if (round === 1) {
                if (d.smeFocus >= 70) {                 // default (75) now lands in the decisive-SME band
                    confidenceChange = 8 + (d.riskTolerance > 6 ? 5 : 0);
                    churnChange = -0.5;
                    newClients = 2;
                } else if (d.smeFocus >= 40) {
                    confidenceChange = 2;
                    churnChange = 0;
                    newClients = 1;
                } else {
                    confidenceChange = -8;
                    churnChange = 0.5;
                    newClients = 0;
                }
                if (d.monthlySpend < 10) {
                    confidenceChange -= 3;
                }
            } else if (round === 2) {
                var simpScore = 0;
                if (d.smeFocus >= 80) {
                    simpScore = 3;
                    churnChange = -1.5;
                    newClients = 3;
                } else if (d.smeFocus >= 60) {
                    simpScore = 2;
                    churnChange = -0.8;
                    newClients = 2;
                } else {
                    simpScore = 0;
                    churnChange = 0.3;
                    newClients = 0;
                }
                if (d.riskTolerance > 7) {
                    churnChange -= 0.5;
                    newClients += 1;
                    confidenceChange = simpScore > 1 ? 6 : -5;
                } else if (d.riskTolerance >= 4) {
                    confidenceChange = simpScore * 3;
                } else {
                    confidenceChange = simpScore;
                    newClients = Math.max(0, newClients - 1);
                }
                // Underfunding onboarding slows acquisition rather than lowering per-client ARR.
                if (d.monthlySpend < 15) {
                    newClients = Math.max(0, newClients - 1);
                }
            } else if (round === 3) {
                if (d.smeFocus >= 75 && d.smeFocus <= 90) {
                    confidenceChange = 15 + Math.min(d.riskTolerance, 7);
                } else if (d.smeFocus > 90) {
                    confidenceChange = 8;
                } else if (d.smeFocus >= 55) {
                    confidenceChange = 3;
                } else {
                    confidenceChange = -12;
                }
                if (d.monthlySpend >= 15 && d.monthlySpend <= 30) {
                    confidenceChange += 5;
                } else if (d.monthlySpend > 35) {
                    confidenceChange -= 8;
                }
                if (d.riskTolerance >= 5 && d.riskTolerance <= 7) {
                    confidenceChange += 4;
                } else if (d.riskTolerance > 7) {
                    confidenceChange += 2;
                }
                churnChange = -0.3;
                newClients = 1;
            } else if (round === 4) {
                var execScore = (d.smeFocus / 100) * (Math.min(d.monthlySpend, 40) / 30) * (d.riskTolerance / 7);
                newClients = Math.round(3 + execScore * 5);
                churnChange = d.smeFocus > 70 ? -1.2 : -0.3;
                confidenceChange = Math.round(execScore * 8);
                if (d.monthlySpend >= 20 && d.monthlySpend <= 40) {
                    newClients += 2;
                }
            }

            // ---- Churn now has teeth: it erodes the active client base every round. ----
            // (Concept §9.2 error #5: 8% monthly churn is "the cancer of the business".)
            var clientsBefore = ds.clientsSme;
            var churnRate = ds.churnMonthly / 100;                       // uses this round's starting churn
            var churnedClients = Math.round(clientsBefore * churnRate);
            var netClients = clientsBefore + newClients - churnedClients;
            ds.clientsSme = Math.max(0, netClients);

            // ARR is driven directly by the active client base × ARPU (Concept §7: $12.4K/yr).
            var arrBefore = ds.arr;
            ds.arr = Math.round(ds.clientsSme * ARPU * 10) / 10;
            arrChangeRaw = Math.round((ds.arr - arrBefore) * 10) / 10;

            // Metrics.
            ds.churnMonthly = Math.max(2, Math.round((ds.churnMonthly + churnChange) * 10) / 10);
            ds.investorConfidence = Math.max(0, Math.min(100, Math.round(ds.investorConfidence + confidenceChange)));
            ds.momGrowth = newClients > churnedClients ? Math.min(15, ds.momGrowth + 2) : Math.max(1, ds.momGrowth - 1);
            ds.nrr = Math.round(100 - ds.churnMonthly * 0.8);

            // ---- Runway now models the real burn: fixed opex + discretionary budget − revenue. ----
            var monthlyRevenue = ds.arr / 12;
            var totalBurn = ds.baseOpex + d.monthlySpend;
            var netBurn = totalBurn - monthlyRevenue;
            ds.cashOnHand = Math.round((ds.cashOnHand - Math.max(0, netBurn)) * 10) / 10;
            if (netBurn > 0) {
                ds.runwayMonths = Math.max(0, Math.min(36, Math.round(ds.cashOnHand / netBurn)));
            } else {
                ds.runwayMonths = 36;   // cash-flow positive: display caps at "36" (i.e. 36+)
            }

            ds.arrHistory.push(ds.arr);
            ds.confidenceHistory.push(ds.investorConfidence);
            ds.churnHistory.push(ds.churnMonthly);
            ds.runwayHistory.push(ds.runwayMonths);

            this._showFeedback(state, round, newClients, churnedClients, arrChangeRaw, confidenceChange, churnChange);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                smeFocus: d.smeFocus,
                monthlySpend: d.monthlySpend,
                riskTolerance: d.riskTolerance,
                newClients: newClients,
                churnedClients: churnedClients,
                arrChange: arrChangeRaw,
                confidenceChange: confidenceChange,
                churnChange: Math.round(churnChange * 10) / 10,
                arr: ds.arr,
                cashOnHand: ds.cashOnHand,
                clientsSme: ds.clientsSme,
                churnMonthly: ds.churnMonthly,
                investorConfidence: ds.investorConfidence,
                runwayMonths: ds.runwayMonths
            };
        }

        _showFeedback(state, round, newClients, churnedClients, arrChange, confidenceChange, churnChange) {
            var panel = document.getElementById('feedbackPanel');
            var textEl = document.getElementById('feedbackText');
            if (!panel || !textEl) return;
            panel.style.display = 'block';
            var t = function(k) { return window.mySimulation.t(k); };
            var ds = state.domainState;
            var msg = '';

            if (round === 1) {
                if (confidenceChange > 5) { msg = t('r1_good'); }
                else if (confidenceChange > 0) { msg = t('r1_mixed'); }
                else { msg = t('r1_bad'); }
            } else if (round === 2) {
                if (newClients >= 3 && churnChange < -1) { msg = t('r2_good'); }
                else if (newClients >= 1) { msg = t('r2_mixed'); }
                else { msg = t('r2_bad'); }
            } else if (round === 3) {
                if (confidenceChange >= 15) { msg = t('r3_good'); }
                else if (confidenceChange >= 5) { msg = t('r3_mixed'); }
                else { msg = t('r3_bad'); }
            } else if (round === 4) {
                // Thresholds aligned with the narrative Series-A target ($400K ARR, churn < 6%).
                if (ds.arr >= 400 && ds.churnMonthly <= 6) { msg = t('r4_good'); }
                else if (ds.arr >= 300) { msg = t('r4_mixed'); }
                else { msg = t('r4_bad'); }
            }

            // Per-round net-client line makes the churn trade-off explicit.
            msg += '<br><br>';
            msg += t('fb_acquired') + ' <b>+' + newClients + '</b>';
            msg += '  |  ' + t('fb_churned') + ' <b>−' + churnedClients + '</b>';
            msg += '  |  ' + t('fb_net') + ' <b>' + (newClients - churnedClients >= 0 ? '+' : '') + (newClients - churnedClients) + '</b>';
            msg += '<br>';
            msg += '📊 ARR: $' + Math.round(ds.arr) + 'K';
            msg += '  |  ' + t('churn_label') + ': ' + ds.churnMonthly + '%';
            msg += '  |  ' + t('confidence_label') + ': ' + ds.investorConfidence + '%';
            msg += '  |  ' + t('runway_label') + ': ' + ds.runwayMonths + (ds.runwayMonths >= 36 ? '+' : '');

            textEl.innerHTML = msg;
        }

